@using sv_642512cd4dc1412faf80e8964c91c7f7.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <span class="step-label">@StepNames[stepIndex]</span>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @* Step Content *@
    <div class="step-content">
        @if (_submitted)
        {
            <div class="confirmation">
                <h2>✓ Application Submitted!</h2>
                <p>Your application has been received. Your application ID is:</p>
                <p class="application-id">@_applicationId</p>
            </div>
        }
        else if (_currentStep == 0)
        {
            @* Step 1: Personal Info *@
            <h2>Personal Information</h2>
            <div class="form-group">
                <label>Full Name *</label>
                <input type="text" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label>Email *</label>
                <input type="email" @bind="_email" placeholder="Enter your email" />
                @if (!string.IsNullOrEmpty(_emailError))
                {
                    <span class="error">@_emailError</span>
                }
            </div>
            <div class="form-group">
                <label>Phone *</label>
                <input type="tel" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label>Address *</label>
                <input type="text" @bind="_address" placeholder="Enter your address" />
            </div>

            @if (!string.IsNullOrEmpty(_validationError))
            {
                <div class="error">@_validationError</div>
            }

            <div class="button-group">
                <button class="btn-next" @onclick="NextStep" disabled="@_isValidating">
                    @(_isValidating ? "Validating..." : "Next")
                </button>
            </div>
        }
        else if (_currentStep == 1)
        {
            @* Step 2: Work History *@
            <h2>Work History</h2>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="_workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                            <label class="checkbox-label">
                                <input type="checkbox" @bind="_workEntries[index].IsCurrent" />
                                Currently working here
                            </label>
                        </div>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="_workEntries[index].Description" placeholder="Describe your responsibilities and achievements"></textarea>
                    </div>
                </div>
            }

            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>

            @if (!string.IsNullOrEmpty(_validationError))
            {
                <div class="error">@_validationError</div>
            }

            <div class="button-group">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        }
        else if (_currentStep == 2)
        {
            @* Step 3: References *@
            <h2>References</h2>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (_references.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
                        </div>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="_references[index].Email" placeholder="Email address" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="_references[index].Phone" placeholder="Phone number" />
                        </div>
                    </div>
                </div>
            }

            @if (_references.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }

            @if (!string.IsNullOrEmpty(_validationError))
            {
                <div class="error">@_validationError</div>
            }

            <div class="button-group">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        }
        else if (_currentStep == 3)
        {
            @* Step 4: Cover Letter *@
            <h2>Cover Letter</h2>
            <div class="form-group">
                <textarea class="cover-letter-textarea" @bind="_coverLetter" @bind:event="oninput"
                          placeholder="Write your cover letter here..." maxlength="2000"></textarea>
                <div class="char-count @(_coverLetter.Length > 2000 ? "over-limit" : "")">
                    @_coverLetter.Length / 2000 characters
                </div>
            </div>

            @if (!string.IsNullOrEmpty(_validationError))
            {
                <div class="error">@_validationError</div>
            }

            <div class="button-group">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        }
        else if (_currentStep == 4)
        {
            @* Step 5: Review & Submit *@
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                </div>
                <dl>
                    <dt>Full Name</dt><dd>@_fullName</dd>
                    <dt>Email</dt><dd>@_email</dd>
                    <dt>Phone</dt><dd>@_phone</dd>
                    <dt>Address</dt><dd>@_address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                @foreach (var reference in _references)
                {
                    <div class="review-entry">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        <span>@reference.Email | @reference.Phone</span>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <p class="cover-letter-preview">@_coverLetter</p>
            </div>

            @if (!string.IsNullOrEmpty(_validationError))
            {
                <div class="error">@_validationError</div>
            }

            <div class="button-group">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @(_isSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        }
    </div>
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private int _highestCompletedStep = -1;
    private string _validationError = "";
    private string _emailError = "";
    private bool _isValidating = false;
    private bool _isSubmitting = false;
    private bool _submitted = false;
    private int _applicationId;

    // Step 1 fields
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 fields
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string _coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int step) => step <= _highestCompletedStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            _currentStep = step;
            _validationError = "";
            _emailError = "";
        }
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
        _validationError = "";
        _emailError = "";
    }

    private async Task NextStep()
    {
        _validationError = "";
        _emailError = "";

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            StateHasChanged();
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;
            if (!emailValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _validationError = "";
            _emailError = "";
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _validationError = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default)
                    {
                        _validationError = "Company name, job title, and start date are required for all positions.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var reference in _references)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                        string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
                    {
                        _validationError = "All fields are required for each reference.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _validationError = "Cover letter is required.";
                    return false;
                }
                if (_coverLetter.Length > 2000)
                {
                    _validationError = "Cover letter must not exceed 2000 characters.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _validationError = "";
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _validationError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
"}

