+    background: #6c757d;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    padding: 0.6rem 1.5rem;
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.95rem;
+}
+
+.btn-back:hover {
+    background: #5a6268;
+}
+
+.btn-add {
+    padding: 0.5rem 1rem;
+    background: #f8f9fa;
+    border: 1px dashed #6c757d;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.9rem;
+    color: #495057;
+}
+
+.btn-add:hover {
+    background: #e9ecef;
+}
+
+.btn-remove {
+    padding: 0.3rem 0.8rem;
+    background: #dc3545;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.8rem;
+}
+
+.btn-remove:hover {
+    background: #c82333;
+}
+
+.btn-edit {
+    padding: 0.25rem 0.75rem;
+    background: transparent;
+    color: #0d6efd;
+    border: 1px solid #0d6efd;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.8rem;
+}
+
+.btn-edit:hover {
+    background: #0d6efd;
+    color: #fff;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 200px !important;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.8rem;
+    color: #6c757d;
+    margin-top: 0.3rem;
+}
+
+.char-count.over-limit {
+    color: #dc3545;
+    font-weight: bold;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.3rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #6c757d;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 0.75rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Error */
+.error {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin-top: 0.3rem;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h2 {
+    color: #198754;
+}
+
+.application-id {
+    font-size: 1.5rem;
+    font-weight: bold;
+    color: #0d6efd;
+}
+

